input.command:
cd ~/Documents/Coding/ai-jdm-paper/scoping/scratch_journals/ && for q in "anchor" "anchoring bias judgment" "resource-rational" "adjustment heuristic" "multi-lab replication reanalysis"; do echo "== $q"; sleep 3; curl -s -A "mailto:[email redacted]" "https://api.crossref.org/works?query.bibliographic=$(python3 -c "import urllib.parse,sys;print(urllib.parse.quote(sys.argv[1]))" "$q")&filter=issn:1531-5320,from-pub-date:2021&rows=10&select=DOI,title,published" > scratch_pbr_cr.json; python3 -c "
import json
try:
  d=json.load(open('scratch_pbr_cr.json'))
except Exception as e:
  print('ERR', open('scratch_pbr_cr.json').read()[:200]); raise SystemExit
for it in d['message']['items']:
    print(it['DOI'], '|', it.get('title',[''])[0][:120], '|', it.get('published',{}).get('date-parts'))"; done

